public class Register {
    private ProductCatalog catalog;   // association to 1
    private Sale currentSale;         // association to 0..1

    public Register(ProductCatalog pc) { catalog = pc; }

    public void endSale() { currentSale.becomeComplete(); }

    public void makeNewSale() { currentSale = new Sale(); }
}

public class SalesLineItem {
    private int quantity;                     // simple attribute
    private ProductDescription description;   // reference attribute

    public SalesLineItem(ProductDescription desc, int qty) {
        this.description = desc;
        this.quantity = qty;
    }

    public Money getSubtotal() {
        return description.getPrice().times(quantity);
    }
}

public class Sale {
    private List<SalesLineItem> lineItems = new ArrayList<>();  // 1..*
    private Payment payment;                                    // 0..1

    public void makeLineItem(ProductDescription desc, int qty) {
        lineItems.add(new SalesLineItem(desc, qty));
    }
}

public void enterItem(ItemID id, int qty) {
    ProductDescription desc = catalog.getProductDescription(id);
    currentSale.makeLineItem(desc, qty);
}

public interface Payable { Money amountDue(); }

public abstract class Payment implements Payable {
    protected Money amount;
    public abstract boolean authorize();
    public Money amountDue() { return amount; }
}

public class CashPayment extends Payment {
    public boolean authorize() { return true; }
}

public String readFirstLine(String path) throws IOException {
    BufferedReader in = new BufferedReader(new FileReader(path));
    try {
        return in.readLine();
    } catch (FileNotFoundException e) {
        log("missing: " + path);
        throw e;                 // rethrow to caller
    } finally {
        in.close();              // always runs
    }
}

public class ProductNotFoundException extends Exception {
    public ProductNotFoundException(String id) {
        super("No product with id " + id);
    }
}

public ProductDescription find(String id) throws ProductNotFoundException {
    ProductDescription d = descriptions.get(id);
    if (d == null) throw new ProductNotFoundException(id);
    return d;
}

double divide(double a, double b) {
    if (b == 0) throw std::invalid_argument("divide by zero");
    return a / b;
}

try {
    double r = divide(10, 0);
} catch (const std::invalid_argument& e) {
    std::cerr << e.what() << std::endl;
}
